// Verify reviewer-signed exact records. Keys are externally enrolled, never
// generated by the production workflow. Signatures prove key control, not human identity.
import {parseUniqueJson} from '../sutra-consent/strict-json.js';
import {casePin} from './pinned-investigation.js';
import {AMBIGUITY_FAMILIES} from './semantic-question-engine.js';
const VERSION='sutra-semantic-review-receipt/v1',ADJ='sutra-semantic-adjudication/v1';
const fail=c=>{throw TypeError('SEMANTIC_REVIEW_'+c);};
const exact=(x,k)=>x&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).length===k.length&&k.every(v=>Object.hasOwn(x,v));
const pin=x=>typeof x==='string'&&/^sha256:[a-f0-9]{64}$/.test(x);
const id=x=>typeof x==='string'&&/^[A-Za-z0-9_.:-]{1,160}$/.test(x);
const str=(x,n)=>typeof x==='string'&&x.trim()===x&&x.length>0&&x.length<=n&&!/[\u0000-\u001f\u007f\ud800-\udfff]/u.test(x);
const hex=(x,n)=>{if(typeof x!=='string'||x.length!==n*2||!/^[a-f0-9]+$/.test(x))fail('HEX');return Uint8Array.from(x.match(/../g),v=>parseInt(v,16));};
const enc=new TextEncoder();
async function verifyEnvelope(envelope,registry){
 if(!exact(envelope,['payloadText','payloadPin','signature'])||typeof envelope.payloadText!=='string'||enc.encode(envelope.payloadText).length>16384||!pin(envelope.payloadPin)||await casePin(envelope.payloadText)!==envelope.payloadPin)fail('PIN');
 const payload=parseUniqueJson(envelope.payloadText,{maxChars:16384,maxDepth:8}),row=registry.find(k=>k.keyId===payload.reviewerKeyId);
 if(!row)fail('KEY');
 const key=await crypto.subtle.importKey('raw',hex(row.publicKeyHex,32),'Ed25519',false,['verify']);
 if(!await crypto.subtle.verify('Ed25519',key,hex(envelope.signature,64),enc.encode(envelope.payloadText)))fail('SIGNATURE');
 return {payload,pin:envelope.payloadPin,key:row};
}
function validateRegistry(registry){
 if(!Array.isArray(registry)||registry.length<3||registry.length>100||registry.some(k=>!exact(k,['keyId','publicKeyHex','role'])||!id(k.keyId)||!['reviewer','adjudicator'].includes(k.role)||typeof k.publicKeyHex!=='string'||!/^[a-f0-9]{64}$/.test(k.publicKeyHex))||new Set(registry.map(k=>k.keyId)).size!==registry.length||new Set(registry.map(k=>k.publicKeyHex)).size!==registry.length)fail('REGISTRY');
}
function label(x){
 if(!['AMBIGUOUS','UNAMBIGUOUS','UNSURE'].includes(x.ambiguity)||!(x.ambiguity==='AMBIGUOUS'?AMBIGUITY_FAMILIES.includes(x.primaryFamily):x.primaryFamily===null)||!Array.isArray(x.readings)||x.readings.length>6||new Set(x.readings).size!==x.readings.length||x.readings.some(s=>!str(s,1000))||x.ambiguity==='AMBIGUOUS'&&x.readings.length<2||x.ambiguity==='UNAMBIGUOUS'&&x.readings.length!==1||!str(x.rationale,1500))fail('LABEL');
}
function review(p,stage,casePinValue,predictionPin,blindPin){
 if(!exact(p,['version','reviewerKeyId','stage','casePin','predictionPin','blindPin','ambiguity','primaryFamily','readings','resolution','rationale','elapsedMs'])||p.version!==VERSION||p.stage!==stage||p.casePin!==casePinValue||p.predictionPin!==predictionPin||p.blindPin!==blindPin||!Number.isSafeInteger(p.elapsedMs)||p.elapsedMs<0||p.elapsedMs>86400000||!(stage==='BLIND'?p.resolution===null:['CORRECT','INCORRECT','UNRESOLVED'].includes(p.resolution)))fail('STAGE');
 label(p);
}
export async function verifySemanticAdjudication({caseText,expectedCasePin,predictionText,expectedPredictionPin,registry,blindReviews,predictionReviews,adjudication}={}){
 validateRegistry(registry);
 if(!pin(expectedCasePin)||!pin(expectedPredictionPin)||await casePin(caseText)!==expectedCasePin||await casePin(predictionText)!==expectedPredictionPin||!Array.isArray(blindReviews)||blindReviews.length!==2||!Array.isArray(predictionReviews)||predictionReviews.length!==2)fail('INPUT');
 const c=parseUniqueJson(caseText,{maxChars:16384,maxDepth:8}),pred=parseUniqueJson(predictionText,{maxChars:16384,maxDepth:8});
 if(!exact(c,['id','scenario','question','context','cohort'])||!id(c.id)||!id(c.scenario)||!str(c.question,2048)||typeof c.context!=='string'||c.context.length>8192||!['external_public','model_authored_challenge','independent_new'].includes(c.cohort)||!exact(pred,['id','casePin','prediction','readings','method'])||pred.id!==c.id||pred.casePin!==expectedCasePin||!['AMBIGUOUS','UNAMBIGUOUS','ABSTAIN'].includes(pred.prediction)||!Array.isArray(pred.readings)||pred.readings.length>8||pred.readings.some(s=>!str(s,1000))||!str(pred.method,200)||pred.prediction==='ABSTAIN'&&pred.readings.length)fail('CASE_OR_PREDICTION');
 const blind=await Promise.all(blindReviews.map(e=>verifyEnvelope(e,registry))),reviews=await Promise.all(predictionReviews.map(e=>verifyEnvelope(e,registry)));
 for(const b of blind){if(b.key.role!=='reviewer')fail('REVIEWER_ROLE');review(b.payload,'BLIND',expectedCasePin,null,null);}
 if(new Set(blind.map(b=>b.key.keyId)).size!==2||new Set(reviews.map(b=>b.key.keyId)).size!==2)fail('REVIEWER_SEPARATION');
 for(const r of reviews){const b=blind.find(x=>x.key.keyId===r.key.keyId);if(!b||r.key.role!=='reviewer')fail('REVIEWER_SEPARATION');review(r.payload,'PREDICTION_REVIEW',expectedCasePin,expectedPredictionPin,b.pin);}
 const final=await verifyEnvelope(adjudication,registry),a=final.payload;
 if(final.key.role!=='adjudicator'||blind.some(x=>x.key.keyId===final.key.keyId)||!exact(a,['version','reviewerKeyId','casePin','predictionPin','blindReceiptPins','reviewReceiptPins','ambiguity','primaryFamily','readings','resolution','rationale','elapsedMs'])||a.version!==ADJ||a.casePin!==expectedCasePin||a.predictionPin!==expectedPredictionPin||!Array.isArray(a.blindReceiptPins)||JSON.stringify(a.blindReceiptPins.slice().sort())!==JSON.stringify(blind.map(x=>x.pin).sort())||!Array.isArray(a.reviewReceiptPins)||JSON.stringify(a.reviewReceiptPins.slice().sort())!==JSON.stringify(reviews.map(x=>x.pin).sort())||!['CORRECT','INCORRECT','UNRESOLVED'].includes(a.resolution)||!Number.isSafeInteger(a.elapsedMs)||a.elapsedMs<0||a.elapsedMs>86400000||pred.prediction==='ABSTAIN'&&a.resolution!=='UNRESOLVED')fail('ADJUDICATION');
 label(a);
 const scoredLabel=a.ambiguity==='UNSURE'?null:{id:c.id,scenario:c.scenario,family:a.primaryFamily,ambiguous:a.ambiguity==='AMBIGUOUS',reviewReceiptPins:reviews.map(x=>x.pin),adjudicationPin:final.pin,judgedResolution:a.resolution,reviewedPredictionPin:expectedPredictionPin};
 return {schema:'sutra-verified-semantic-adjudication/v1',caseId:c.id,cohort:c.cohort,scoredLabel,prediction:{id:c.id,prediction:pred.prediction,predictionPin:expectedPredictionPin},blindAgreement:blind[0].payload.ambiguity===blind[1].payload.ambiguity,blindFamilyAgreement:blind[0].payload.primaryFamily===blind[1].payload.primaryFamily,reviewAgreement:reviews[0].payload.resolution===reviews[1].payload.resolution,elapsedMs:{blind:blind.map(x=>x.payload.elapsedMs),predictionReview:reviews.map(x=>x.payload.elapsedMs),adjudication:a.elapsedMs},keyControlVerified:true,independentHumanIdentity:'EXTERNAL_ATTESTATION_REQUIRED',decisionAuthority:'NONE'};
}
